//! Real files.
use crate::format::MAX_FILE_LEN;
use crate::io::{Dir, Medium};
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};

/// A directory on disk holding one wallet's journal.
pub struct FsDir {
    path: PathBuf,
}

/// A journal or snapshot file.
pub struct FsFile {
    file: File,
}

/// Exclusive lock on the directory; released when dropped.
pub struct FsLock {
    _file: File,
}

const LOCK_NAME: &str = "lock";

/// File names are generated by this crate, but nothing outside the fixed
/// alphabet is ever turned into a path.
fn checked(name: &str) -> io::Result<&str> {
    let ok = !name.is_empty()
        && name.len() <= 64
        && name
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-' || b == b'.')
        && !name.starts_with('.');
    if ok {
        Ok(name)
    } else {
        Err(io::Error::new(io::ErrorKind::InvalidInput, "file name"))
    }
}

fn options() -> OpenOptions {
    let mut o = OpenOptions::new();
    // Plain write access, not append mode: on Windows an append-only handle
    // may not shorten the file, and cutting a torn tail needs that. Appends
    // seek to the end themselves; the directory lock keeps a single writer.
    o.read(true).write(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        // current user only
        o.mode(0o600);
    }
    o
}

impl FsDir {
    /// Use `path`, creating the directory if needed (accessible to the
    /// current user only on Unix; on Windows it inherits the profile ACL).
    pub fn new(path: &Path) -> io::Result<FsDir> {
        if !path.is_dir() {
            let mut b = fs::DirBuilder::new();
            b.recursive(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::DirBuilderExt;
                b.mode(0o700);
            }
            b.create(path)?;
        }
        Ok(FsDir {
            path: path.to_path_buf(),
        })
    }
}

impl Dir for FsDir {
    type File = FsFile;
    type Lock = FsLock;

    fn lock(&self) -> io::Result<FsLock> {
        let mut o = options();
        o.create(true);
        let file = o.open(self.path.join(LOCK_NAME))?;
        match file.try_lock() {
            Ok(()) => Ok(FsLock { _file: file }),
            Err(fs::TryLockError::WouldBlock) => Err(io::Error::new(
                io::ErrorKind::WouldBlock,
                "journal is locked",
            )),
            Err(fs::TryLockError::Error(e)) => Err(e),
        }
    }

    fn list(&self) -> io::Result<Vec<String>> {
        let mut out = Vec::new();
        for entry in fs::read_dir(&self.path)? {
            if let Some(name) = entry?.file_name().to_str() {
                if name != LOCK_NAME {
                    out.push(name.to_owned());
                }
            }
        }
        Ok(out)
    }

    fn open(&self, name: &str) -> io::Result<FsFile> {
        Ok(FsFile {
            file: options().open(self.path.join(checked(name)?))?,
        })
    }

    fn create_new(&self, name: &str) -> io::Result<FsFile> {
        let mut o = options();
        o.create_new(true);
        Ok(FsFile {
            file: o.open(self.path.join(checked(name)?))?,
        })
    }

    fn remove(&self, name: &str) -> io::Result<()> {
        fs::remove_file(self.path.join(checked(name)?))
    }

    fn sync(&self) -> io::Result<()> {
        // Windows offers no way to flush a directory handle; file creation
        // there is made durable by flushing the file itself.
        #[cfg(unix)]
        File::open(&self.path)?.sync_all()?;
        Ok(())
    }
}

impl Medium for FsFile {
    fn len(&mut self) -> io::Result<u64> {
        Ok(self.file.metadata()?.len())
    }

    fn read_all(&mut self) -> io::Result<Vec<u8>> {
        let len = self.len()?;
        if len > MAX_FILE_LEN {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "file too large"));
        }
        self.file.seek(SeekFrom::Start(0))?;
        let mut out = Vec::new();
        // Bounded even if the file grows while being read.
        (&mut self.file).take(MAX_FILE_LEN).read_to_end(&mut out)?;
        Ok(out)
    }

    fn append(&mut self, data: &[u8]) -> io::Result<()> {
        self.file.seek(SeekFrom::End(0))?;
        self.file.write_all(data)
    }

    fn sync(&mut self) -> io::Result<()> {
        self.file.sync_all()
    }

    fn truncate(&mut self, len: u64) -> io::Result<()> {
        self.file.set_len(len)
    }
}
